    C c;
    constructor(C _c) { c = _c; }

    // single public function with all test logic
    // params: amount to send with play, and a dummy bool to observe whether play reverted
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward
        require(address(this).balance >= amount);

        // read pot before
        uint potBefore = c.pot();

        // attempt to call play forwarding `amount`; capture whether it reverted by using low-level call
        // must be a top-level state-changing call to c, so use low-level to call payable function
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        // read pot after
        uint potAfter = c.pot();

        // If the call succeeded (ok==true) then pot must have increased exactly by the forwarded amount
        // This captures the difference: original requires exact TICKET_AMOUNT so when sending that amount pot increases by it;
        // mutant requires TICKET_AMOUNT+1 so sending TICKET_AMOUNT will revert and ok==false, violating the implication if ok were true.
        assert(!ok || potAfter == potBefore + amount);
    }

    // allow test contract to receive ETH for forwarding
    receive() external payable {}
}

