import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount sent and the caller address
    function testFuzz_property(uint256 sendAmount, address caller) public {
        // keep values in a wide but sensible domain: amount non-zero and not absurdly large
        vm.assume(sendAmount > 0 && sendAmount < type(uint128).max);
        // avoid the zero address for sender to make vm.prank meaningful
        vm.assume(caller != address(0));

        // fund the caller so they can send sendAmount
        vm.deal(caller, sendAmount);

        bool ok;
        // perform the call as the fuzzed caller
        vm.prank(caller);
        try c.play{value: sendAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert (single assertion):
        // If the call succeeded, then c.pot() equals the sent amount added to previous pot (which was 0 at deployment),
        // but since pot starts at 0 in setUp, this reduces to: if call succeeded, pot == sendAmount.
        // This holds for the reference (which accepts exactly TICKET_AMOUNT) for all inputs it accepts;
        // the mutant requiring TICKET_AMOUNT+1 will make the call revert when sendAmount == TICKET_AMOUNT,
        // causing this assertion to fail for that input (fuzzer will find it).
        if (ok) {
            // single required assertion reading c's public getter
            assertTrue(c.pot() == sendAmount);
        } else {
            // if call reverted, then pot must still be zero (no state change on revert)
            assertTrue(c.pot() == 0);
        }
    }
}

