contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz on the caller address and an initial balance for that caller. We will always send exactly 11 wei.
    function testFuzz_property(address caller, uint256 callerBalance) public {
        // Keep domain wide but sensible: non-zero caller and enough balance to send 11 wei
        vm.assume(caller != address(0));
        callerBalance = bound(callerBalance, 0, 1 ether);
        vm.deal(caller, callerBalance);

        bool ok;
        // ensure the caller sends exactly 11 wei
        vm.startPrank(caller);
        try c.play{value: 11}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // General rule: the reference contract always rejects payments of 11 (only accepts 10),
        // so the call should always revert (ok == false) for every admissible caller and balance.
        // The mutant accepts 11 and will make ok == true for some inputs; therefore this assertion
        // holds for the reference for all inputs and fails on the mutant for some input.
        assertTrue(ok == false);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single test function driving the contract once; caller provides the ticket payment amount and
    // an initial deposit to the contract-under-test by sending previous plays through this same test contract.
    // We require this contract has enough balance to pay.
    function runTest(uint ticketPayment) public {
        // require we call with the standard ticket amount
        require(ticketPayment > 0);
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= ticketPayment);

        // Make the decisive play call that in the original C may or may not reset pot depending on randomness.
        // This is the single state-changing call on c in this test.
        c.play{value: ticketPayment}();

        // Observe two public values: the contract's pot and its balance. The rule: if pot is zero then
        // the caller (this test contract) must not have received more than ticketPayment - FEE_AMOUNT extra funds
        // from c in that call. We express this by checking that address(this).balance has not increased by more than ticketPayment - 1
        // relative to the sent ticketPayment. Since we cannot read previous balance directly here, we compare
        // the c.pot() against 0 and assert a relation involving address(c).balance.

        // Read pot and bank (only pot is needed). This is a view call allowed inside assert/require.
        uint potAfter = c.pot();

        // The distinguishing rule: if potAfter == 0 then the contract c's balance must be equal to 0 or small enough
        // because the payout to the caller should have consumed most of c's balance except the fee which goes to bank.
        // We assert that when potAfter == 0, address(c).balance <= 1 (i.e., at most FEE_AMOUNT remains).
        // This holds on the original contract (when payout happens, only FEE_AMOUNT stays with bank so contract balance is 0),
        // but the mutant always empties pot and sends out the accumulated pot minus fee — leaving at most FEE_AMOUNT in c,
        // so the mutant violates the general rule by making this outcome deterministic (the verifier can observe the contradiction).

        assert(!(potAfter == 0) || address(c).balance <= 1);
    }

    // allow funding this test contract
    receive() external payable {}
}

